import json
import math

def round_half_up(value, decimals=2):
    multiplier = 10 ** decimals
    return math.floor(value * multiplier + 0.5) / multiplier

def validate_invoice(data):
    if not isinstance(data, dict):
        return "input must be a JSON object"
    if "lines" not in data:
        return "missing field: lines"
    if "discount_percent" not in data:
        return "missing field: discount_percent"
    if "tax_percent" not in data:
        return "missing field: tax_percent"
    if not isinstance(data["lines"], list):
        return "lines must be an array"
    for i, line in enumerate(data["lines"]):
        if not isinstance(line, dict):
            return f"invalid line at index {i}: not an object"
        if "quantity" not in line:
            return f"missing field: quantity in line {i}"
        if "unit_price" not in line:
            return f"missing field: unit_price in line {i}"
        if not isinstance(line["quantity"], (int, float)):
            return f"invalid quantity in line {i}"
        if not isinstance(line["unit_price"], (int, float)):
            return f"invalid unit_price in line {i}"
        if line["quantity"] < 0:
            return f"invalid quantity in line {i}"
        if line["unit_price"] < 0:
            return f"invalid unit_price in line {i}"
    dp = data["discount_percent"]
    tp = data["tax_percent"]
    if not isinstance(dp, (int, float)):
        return "discount_percent must be a number"
    if dp < 0 or dp > 100:
        return "discount_percent out of range (0..100)"
    if not isinstance(tp, (int, float)):
        return "tax_percent must be a number"
    if tp < 0 or tp > 50:
        return "tax_percent out of range (0..50)"
    return None

def compute_invoice(data):
    error = validate_invoice(data)
    if error:
        return {"error": error}
    subtotal = round_half_up(sum(line["quantity"] * line["unit_price"] for line in data["lines"]))
    discount = round_half_up(subtotal * data["discount_percent"] / 100)
    discounted_amount = round_half_up(subtotal - discount)
    tax = round_half_up(discounted_amount * data["tax_percent"] / 100)
    total = round_half_up(discounted_amount + tax)
    return {
        "subtotal": subtotal,
        "discount": discount,
        "tax": tax,
        "total": total
    }


def compute_from_json(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError as e:
        return {"error": f"invalid JSON: {e}"}
    return compute_invoice(data)

import json
import sys
import os
sys.path.insert(0, os.path.dirname(__file__))

from invoice_calculator import compute_invoice, compute_from_json, round_half_up

def test_acceptance():
    data = {
        "lines": [
            {"description": "item1", "quantity": 2, "unit_price": 10.00},
            {"description": "item2", "quantity": 1, "unit_price": 5.50}
        ],
        "discount_percent": 10,
        "tax_percent": 20
    }
    result = compute_invoice(data)
    assert result["subtotal"] == 25.5
    assert result["discount"] == 2.55
    assert result["tax"] == 4.59
    assert result["total"] == 27.54

def test_negative_quantity():
    data = {
        "lines": [{"description": "item1", "quantity": -1, "unit_price": 5.00}],
        "discount_percent": 0,
        "tax_percent": 0
    }
    result = compute_invoice(data)
    assert "error" in result
    assert "quantity" in result["error"]

def test_negative_unit_price():
    data = {
        "lines": [{"description": "item1", "quantity": 1, "unit_price": -5.00}],
        "discount_percent": 0,
        "tax_percent": 0
    }
    result = compute_invoice(data)
    assert "error" in result
    assert "unit_price" in result["error"]

def test_discount_percent_out_of_range_high():
    data = {
        "lines": [{"description": "item1", "quantity": 1, "unit_price": 10.00}],
        "discount_percent": 101,
        "tax_percent": 20
    }
    result = compute_invoice(data)
    assert "error" in result
    assert "discount_percent" in result["error"]

def test_tax_percent_out_of_range_high():
    data = {
        "lines": [{"description": "item1", "quantity": 1, "unit_price": 10.00}],
        "discount_percent": 0,
        "tax_percent": 51
    }
    result = compute_invoice(data)
    assert "error" in result
    assert "tax_percent" in result["error"]

def test_missing_lines():
    data = {"discount_percent": 0, "tax_percent": 0}
    result = compute_invoice(data)
    assert "error" in result
    assert "lines" in result["error"]

def test_missing_field():
    data = {"lines": [], "tax_percent": 0}
    result = compute_invoice(data)
    assert "error" in result
    assert "discount_percent" in result["error"]

def test_invalid_json():
    result = compute_from_json("{invalid")
    assert "error" in result
    assert "JSON" in result["error"]

def test_round_half_up():
    assert round_half_up(2.345, 2) == 2.35
    assert round_half_up(2.344, 2) == 2.34
    assert round_half_up(2.5, 0) == 3

def test_quantity_zero():
    data = {
        "lines": [{"description": "free", "quantity": 0, "unit_price": 100.00}],
        "discount_percent": 0,
        "tax_percent": 0
    }
    result = compute_invoice(data)
    assert "error" not in result
    assert result["subtotal"] == 0.0
    assert result["total"] == 0.0

def test_price_zero():
    data = {
        "lines": [{"description": "free", "quantity": 5, "unit_price": 0.00}],
        "discount_percent": 0,
        "tax_percent": 0
    }
    result = compute_invoice(data)
    assert "error" not in result
    assert result["subtotal"] == 0.0
    assert result["total"] == 0.0

